// Docs screenshots of the documentary crew (timeline) and Angela's ledger, with demo / mocked data only.
// Regenerated by `npm run screenshots` along with the others.
import { fileURLToPath } from 'node:url';
import { expect, test } from '@playwright/test';
import type { UsageReport } from '../../shared/observability';
import { DEMO_SNAPSHOT } from '../../shared/fixtures/demo-snapshot';
import { demoUsage } from '../src/observability/demoObservability';
import { liveServer, noServer, person } from './helpers';

const out = (name: string) => fileURLToPath(new URL(`../../docs/screenshots/${name}`, import.meta.url));

test.describe('@screenshot timeline and ledger screenshots', () => {
  test('a bot\'s timeline: the documentary crew', async ({ page }) => {
    await noServer(page);
    await page.goto('/?demo=1');
    await expect(page.locator('[data-person]')).toHaveCount(23);
    await page.waitForTimeout(1600);
    await person(page, /^Dwight Schrute — /).click();
    const win = page.getByRole('dialog', { name: 'Dwight Schrute' });
    await win.getByRole('tab', { name: 'Timeline' }).click();
    await expect(win.getByTestId('talking-head')).toContainText('Today Dwight');
    await page.screenshot({ path: out('timeline.png') });
  });

  test('Angela\'s ledger', async ({ page }) => {
    const r = demoUsage(DEMO_SNAPSHOT, '7d');
    const report: UsageReport = {
      ...r, rows: [...r.rows, { personId: 'temp-claude-code-paper-site', name: 'paper-site (Claude Code)', adapterId: 'claude-code', adapterLabel: 'Claude Code', usage: null, unavailable: 'No usage data from Claude Code' }],
    };
    await liveServer(page);
    await page.route('**/api/usage*', (route) => route.fulfill({ json: { ...report, period: new URL(route.request().url()).searchParams.get('period') ?? 'today' } }));
    await page.goto('/');
    await expect(page.locator('[data-person]')).toHaveCount(23);
    await page.waitForTimeout(1600);
    await page.getByRole('button', { name: /^Angela’s ledger/ }).click();
    const win = page.getByRole('dialog', { name: 'Angela’s ledger' });
    await win.getByRole('tab', { name: '7 days' }).click();
    await expect(win.getByTestId('ledger-total')).toBeVisible();
    await page.screenshot({ path: out('ledger.png') });
  });
});
